const STEP2 = `Subject: Next step for {{ collective_name }} — your application to {{ org_name }}

Hi,

Thanks for applying to {{ org_name }} with {{ collective_name }}
({{ collective_url }}).

An automated first read of your public Open Collective page raised nothing to pass on.
That is not a decision. A person reviews every application.

One step left. Please fill in the application form linked below. The more detail
you give, the better the human review.

{{ form_url }}

It takes about ten minutes. If anything is unclear, reply to this email and a human will
get back to you.

{{ legal_name_note }}

— {{ org_name }}`;
const ADVISED_WRONG_HOST = `Subject: Your application to {{ org_name }} for {{ collective_name }} — next step

Hi,

Thanks for applying to {{ org_name }} with {{ collective_name }}
({{ collective_url }}).

Before a person reviews your application, an automated check reads what is
currently on your Open Collective page. Its first impression, based only on
that:

{{ ai_applicant_message }}

That is a machine's reading of a short description. It is not a decision, and
it may simply be wrong. A person will review your application either way.

The next step is the same for everyone. Please fill in the application form
linked below.

{{ form_url }}

The more detail you give in the form, the better the human review. And if the
other host really is the better fit, applying there instead is completely fine.

Questions or disagreement? Reply to this email and a reviewer will read it.

{{ legal_name_note }}

— {{ org_name }}`;
const ADVISED_NOT_OPEN_SOURCE = `Subject: Your application to {{ org_name }} for {{ collective_name }} — next step

Hi,

Thanks for applying to {{ org_name }} with {{ collective_name }}
({{ collective_url }}).

Before a person reviews your application, an automated check reads what is
currently on your Open Collective page. Its first impression, based only on
that:

{{ ai_applicant_message }}

That is a machine's reading of what may be a very short description. It is
not a decision, and it may simply be wrong. A person will review your
application either way.

The next step is the same for everyone. Please fill in the application form
linked below.

{{ form_url }}

The more detail you give in the form, the better the human review. Tell us
what the project does and how it connects to open source. If you have a
repository and a licence, include them. If you run a service on open source
software rather than writing your own, the form has an option for that, and it
asks you for neither.

Questions or disagreement? Reply to this email and a reviewer will read it.

{{ legal_name_note }}

— {{ org_name }}`;
const ADVISED_UNCLEAR = `Subject: Your application to {{ org_name }} for {{ collective_name }}: next step

Hi,

Thanks for applying to {{ org_name }} with {{ collective_name }}
({{ collective_url }}).

Before a person reviews your application, an automated check reads what is
currently on your Open Collective page. That page did not show it how your
work connects to open source. Its first impression, based only on that:

{{ ai_applicant_message }}

That is a machine's reading of what may be a very short description. It is not
a decision, and it may simply be wrong. A person will review your application
either way.

The next step is the same for everyone. Please fill in the application form
linked below.

{{ form_url }}

The form is where you can tell us what the page could not. Its first question
asks what you are applying as. If you run infrastructure or a service for a
community, choose that option. The form then asks which open source software
you run, and it does not ask you for a repository or a licence.

Questions or disagreement? Reply to this email and a reviewer will read it.

{{ legal_name_note }}

— {{ org_name }}`;
const TEMPLATES = {
  fits: STEP2,
  wrong_host: ADVISED_WRONG_HOST,
  not_open_source: ADVISED_NOT_OPEN_SOURCE,
  unclear: ADVISED_UNCLEAR,
};
const ORG_NAMES = { OSE: 'Open Source Europe' };
const row = $json;
const recipient = row.contact_email || row.applicant_email;
if (!recipient) throw new Error(`form invitation: no address for ${row.slug}`);
const raw = TEMPLATES[row.ai_verdict];
if (!raw) throw new Error(`form invitation: unknown verdict "${row.ai_verdict}" for ${row.slug}`);
// Which template went out is a difference a reviewer cannot see from the row: the fits
// path sends the form link alone, every other verdict sends the advisory note above it.
// This is the only place that mapping lives, so hand the answer downstream as one field
// rather than deriving the verdict a second time in the Slack reply.
const advisoryNoteIncluded = raw !== STEP2;
// The emailed link prefills page 1's Open Collective URL field, so the applicant does
// not retype what we already know. n8n keys prefill query parameters on the field's
// LABEL, percent-encoded, and only in production mode.
const FORM_FIELD = "Your collective's Open Collective URL";
const formBase = ($env.FORM_URL_OSE || '').replace(/\/+$/, '');
const formUrl = row.collective_url
  ? `${formBase}?${encodeURIComponent(FORM_FIELD)}=${encodeURIComponent(row.collective_url)}`
  : formBase;
// Admins with no legal name on Open Collective get a firm request to add one now, and
// everyone else nothing. It asks, it never holds the application back.
// Find admins without a legal name only lists names it could check, so a token without the
// account scope or a failed request leaves the paragraph out rather than tell every
// applicant something that may be wrong. The names are the admins' public display names.
const wrap = (text, width) => {
  const lines = [];
  let line = '';
  text.split(/\s+/).filter(Boolean).forEach((word) => {
    if (line && (line + ' ' + word).length > width) {
      lines.push(line);
      line = word;
    } else {
      line = line ? line + ' ' + word : word;
    }
  });
  if (line) lines.push(line);
  return lines.join('\n');
};
const listNames = (names) => names.length < 2
  ? names.join('')
  : names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1];
const withoutLegalName = row.legal_name_check === 'checked' && Array.isArray(row.admins_without_legal_name)
  ? row.admins_without_legal_name.filter((n) => typeof n === 'string' && n.trim() !== '')
  : [];
const legalNameNote = withoutLegalName.length === 0 ? '' : [
  'Please also make sure every admin has their full legal name, as it appears on'
  + ' their official ID, on their Open Collective profile. '
  + listNames(withoutLegalName)
  + (withoutLegalName.length === 1 ? ' has' : ' have')
  + ' not added one yet, so please make sure it is added now.',
  'We ask for it early because anyone the collective pays or reimburses needs it.'
  + ' We check it against the bank details on every expense, and we cannot pay an'
  + ' expense from a profile without one. Each admin should also be a real person'
  + ' with their own profile, not an account shared by several people.',
  'Open Collective keeps the legal name private. Only the admin and we, as your'
  + ' fiscal host, can see it, so a nickname can stay the public name. To add it, log'
  + ' in to Open Collective, open your Dashboard, go to Settings, then Info, and fill'
  + ' in the Legal name field.',
].map((paragraph) => wrap(paragraph, 80)).join('\n\n');
const vars = {
  collective_name: row.collective_name,
  collective_url: row.collective_url,
  org_name: ORG_NAMES[row.org] || row.org,
  form_url: formUrl,
  legal_name_note: legalNameNote,
  // Quote the model's words so the applicant can see where our voice stops and
  // the automated read begins. Plain text has no other way to mark a quote, and
  // mail clients style a > prefix as one.
  ai_applicant_message: String(row.ai_applicant_message || '').trim()
    ? String(row.ai_applicant_message).trim().split('\n').map((l) => `> ${l}`.trimEnd()).join('\n')
    : '',
};
// The only placeholder allowed to be empty. Its line and the blank line after it go too.
const OPTIONAL = new Set(['legal_name_note']);
const render = (tpl) => tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, key) => {
  const value = vars[key];
  if (OPTIONAL.has(key) && value === '') return '';
  if (value === undefined || value === null || value === '') {
    throw new Error(`form invitation: missing "${key}" for ${row.slug}`);
  }
  return String(value);
});
const cut = raw.indexOf('\n');
let subject = render(raw.slice('Subject: '.length, cut));
const body = render(raw.slice(cut).trimStart()).replace(/\n{3,}/g, '\n\n');
// DRY_RUN fails safe: only the exact string `false` releases mail to the applicant. Unset,
// empty, `1`, `yes` or a trailing space all suppress, so a dropped or mistyped line in .env
// cannot quietly start mailing real people. Going live is the deliberate act of writing
// DRY_RUN=false.
const suppressed = String($env.DRY_RUN || '').trim().toLowerCase() !== 'false';
if (suppressed) subject = `[DRY_RUN → would have gone to ${recipient}] ${subject}`;
const to = suppressed ? ($env.DRY_RUN_RECIPIENT || '') : recipient;
if (!to) throw new Error('form invitation: DRY_RUN is not "false", so the email is suppressed, but DRY_RUN_RECIPIENT is empty');
return { json: {
  slug: row.slug, to, subject, body, suppressed, advisory_note_included: advisoryNoteIncluded,
  legal_name_check: row.legal_name_check || 'failed',
  legal_name_check_reason: row.legal_name_check_reason || '',
  admins_without_legal_name: withoutLegalName,
} };

const TEMPLATE = `Subject: Reminder: your application to {{ org_name }} for {{ collective_name }}

Hi,

We sent you a link to the {{ org_name }} application form and haven't had it back yet.

{{ form_url }}

If you're still interested, fill it in when you get a chance. If your plans changed and
you'd rather not go ahead, no need to reply — we'll leave it there.

— {{ org_name }}`;
const ORG_NAMES = { OSE: 'Open Source Europe' };
const row = $json;
const recipient = row.contact_email || row.applicant_email;
if (!recipient) throw new Error(`reminder: no address for ${row.slug}`);
// The emailed link prefills page 1's Open Collective URL field, so the applicant does
// not retype what we already know. n8n keys prefill query parameters on the field's
// LABEL, percent-encoded, and only in production mode.
const FORM_FIELD = "Your collective's Open Collective URL";
const formBase = ($env.FORM_URL_OSE || '').replace(/\/+$/, '');
const formUrl = row.collective_url
  ? `${formBase}?${encodeURIComponent(FORM_FIELD)}=${encodeURIComponent(row.collective_url)}`
  : formBase;
const vars = {
  collective_name: row.collective_name,
  org_name: ORG_NAMES[row.org] || row.org,
  form_url: formUrl,
};
const render = (tpl) => tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, key) => {
  const value = vars[key];
  if (value === undefined || value === null || value === '') {
    throw new Error(`reminder: missing "${key}" for ${row.slug}`);
  }
  return String(value);
});
const cut = TEMPLATE.indexOf('\n');
let subject = render(TEMPLATE.slice('Subject: '.length, cut));
const body = render(TEMPLATE.slice(cut).trimStart());
// DRY_RUN fails safe: only the exact string `false` releases mail to the applicant. Unset,
// empty, `1`, `yes` or a trailing space all suppress, so a dropped or mistyped line in .env
// cannot quietly start mailing real people. Going live is the deliberate act of writing
// DRY_RUN=false.
const suppressed = String($env.DRY_RUN || '').trim().toLowerCase() !== 'false';
if (suppressed) subject = `[DRY_RUN → would have gone to ${recipient}] ${subject}`;
const to = suppressed ? ($env.DRY_RUN_RECIPIENT || '') : recipient;
if (!to) throw new Error('reminder: DRY_RUN is not "false", so the email is suppressed, but DRY_RUN_RECIPIENT is empty');
return { json: { slug: row.slug, to, subject, body, suppressed } };

// The invitation sentence is fixed wording. The legal name sentence after it carries the
// admins' public names and an Open Collective error message, both escaped for Slack: & first,
// then < and >, so Slack reads them as text and not as a control sequence.
//
// Two different emails go out under this one stage. The fits path sends the form link
// alone, every other verdict sends the advisory note above it, and a reviewer reading
// the thread has no other way to tell which the applicant received. Render form
// invitation decides that, so read its flag back by node name and match on the slug
// rather than deriving the verdict a second time here.
const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const rendered = new Map($('Render form invitation').all().map((item) => [item.json.slug, item.json]));
const withNote = new Map([...rendered].map(([slug, json]) => [slug, json.advisory_note_included]));

// What the email said about legal names. A reviewer needs the unchecked cases most, since
// the applicant then heard nothing and the profiles still need a look by hand.
const legalNames = (json) => {
  if (!json) return '';
  if (json.legal_name_check === 'no_scope') {
    return ' :warning: Admins\' legal names were not checked: the Open Collective token lacks the `account` scope, so the email does not mention them.';
  }
  if (json.legal_name_check !== 'checked') {
    const why = json.legal_name_check_reason ? ` (${escapeSlack(json.legal_name_check_reason)})` : '';
    return ` :warning: Admins' legal names could not be checked on Open Collective${why}, so the email does not mention them.`;
  }
  const names = Array.isArray(json.admins_without_legal_name) ? json.admins_without_legal_name : [];
  if (!names.length) return ' Every admin has a legal name on Open Collective.';
  return ` The email asks ${names.map((n) => `*${escapeSlack(n)}*`).join(', ')} to add their legal name on Open Collective now.`;
};

const WITH_NOTE = ':envelope_with_arrow: Form invitation sent, with the advisory note above included in the email.';
const WITHOUT_NOTE = ':envelope_with_arrow: Form invitation sent. The first read raised nothing to pass on, so the email is the form link only.';
// No flag means the two node outputs did not line up, which should not happen. Say the
// less rather than say the wrong thing.
const UNKNOWN = ':envelope_with_arrow: Form invitation sent to the applicant.';

return $input.all()
  .filter((item) => item.json.slack_thread_ts && item.json.slack_channel_id)
  .map((item) => {
    const row = item.json;
    const flag = withNote.get(row.slug);
    return { json: {
      slug: row.slug,
      channel: row.slack_channel_id,
      thread_ts: row.slack_thread_ts,
      text: (flag === undefined ? UNKNOWN : (flag ? WITH_NOTE : WITHOUT_NOTE)) + legalNames(rendered.get(row.slug)),
    } };
  });

// Every word of this message is fixed, so there is nothing to escape for Slack: no
// applicant, collective or model text is interpolated into it.
return $input.all()
  .filter((item) => item.json.slack_thread_ts && item.json.slack_channel_id)
  .map((item) => ({ json: {
    slug: item.json.slug,
    channel: item.json.slack_channel_id,
    thread_ts: item.json.slack_thread_ts,
    text: ':alarm_clock: No form yet. Reminder sent to the applicant',
  } }));

// Escalation is the one stage that asks a person to do something, so it also marks the
// parent. Reviewers scan the channel for parents carrying this reaction.
//
// The collective's name and URL are the applicant's own words, so they are data, not
// markup: a collective named <!channel>, or a masked link like
// <https://evil.example|opencollective.com/theirs> where the URL should be, would otherwise
// be honoured by Slack in the reviewers' channel. Escape the three characters Slack treats
// as control characters, & first so the other two are not escaped twice. Only the
// applicant-derived values go through escapeSlack: the fixed wording keeps its *bold* and
// its :rotating_light:, and org resolves from our own host list.
const ORG_NAMES = { OSE: 'Open Source Europe' };

const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const minutes = Number($env.ESCALATE_AFTER_MINUTES || 10080);
const days = Math.round(minutes / 1440);
return $input.all()
  .filter((item) => item.json.slack_thread_ts && item.json.slack_channel_id)
  .map((item) => {
    const row = item.json;
    const org = ORG_NAMES[row.org] || row.org;
    const text = [
      `:rotating_light: *${escapeSlack(row.collective_name)}* has not filled the form ${days} days after the reminder.`,
      `Someone needs to decide what happens to this application. ${escapeSlack(row.collective_url)}`,
      `Applied to ${org}.`,
    ].join('\n');
    // The Approve and Reject buttons apply 6 answers, as on a submitted form, because a
    // person decides an escalated application too, usually by closing it for lack of a
    // response. Each button carries the slug alone, and apply 6 reads the rest from the row.
    const blocks = [
      { type: 'section', text: { type: 'mrkdwn', text } },
      { type: 'actions', block_id: 'ose_decision', elements: [
        { type: 'button', action_id: 'ose_decide_approve', style: 'primary', value: row.slug,
          text: { type: 'plain_text', text: 'Approve…' } },
        { type: 'button', action_id: 'ose_decide_reject', style: 'danger', value: row.slug,
          text: { type: 'plain_text', text: 'Reject…' } },
      ] },
    ];
    return { json: {
      slug: row.slug,
      channel: row.slack_channel_id,
      thread_ts: row.slack_thread_ts,
      text,
      blocks,
    } };
  });

// Pairs each status response with the row this run just claimed (the HTTP node emits one
// response per input row, in order) and says whether the application is still pending.
//
// Only a pending application gets the invitation. A decision can land on Open
// Collective before this sweep reaches the row: a collective moving from another host
// after agreeing it with OSE is approved within a minute of applying, and asking it to
// fill in the form afterwards is wrong. The readings are the ones Extract decision uses
// in apply 1a and 1b:
//
//   host.slug === host_slug, isApproved false -> pending: invite
//   host.slug === host_slug, isApproved true  -> approved: skip
//   host === null                             -> rejected or withdrawn: skip
//   host.slug is a different host             -> hosted elsewhere: skip
//   no collective with that slug any more     -> gone: skip
//
// This node only decides whether to invite. Recording the decision stays with the
// decision sweep in apply 1a and 1b, so it happens in one place. An errors array throws,
// as every Open Collective read here does. A response that is none of the shapes above
// drops that row alone, neither invited nor marked skipped: its claim goes stale and a
// later sweep asks again, and the other rows in the batch are still invited.
const rows = $('Claim the row for the invitation').all();
const out = [];
$input.all().forEach((item, i) => {
  const row = rows[i].json;
  const body = item.json || {};
  const errors = Array.isArray(body.errors) ? body.errors : [];
  const gone = !(body.data && body.data.account)
    && typeof row.slug === 'string' && row.slug !== '' && row.slug === row.slug.trim()
    && errors.length > 0
    && errors.every((e) => e && e.message === `No collective found with slug ${row.slug}`);
  if (errors.length && !gone) {
    throw new Error(`invitation: Open Collective refused the status query for ${row.slug}: ${JSON.stringify(body.errors)}`);
  }
  const account = body.data && body.data.account;
  if (!account && !gone) return; // no account and no error: ask again on a later sweep
  if (account && !('host' in account)) return; // not a host-bearing account type: leave it
  const host = account && account.host ? account.host.slug : null;
  let ocState;
  if (gone) ocState = 'gone';
  else if (host === row.host_slug) ocState = account.isApproved === true ? 'approved' : 'pending';
  else if (host === null) ocState = 'rejected';
  else ocState = 'elsewhere';
  out.push({ json: {
    ...row,
    oc_state: ocState,
    oc_other_host: ocState === 'elsewhere' ? host : '',
    oc_approved_at: ocState === 'approved' ? (account.approvedAt || '') : '',
  }, pairedItem: { item: i } });
});
return out;

// Pairs each legal name response with its row and says which admins have no legal name on
// their Open Collective profile. Only the admins' public names leave this node, never a
// legal name.
//
// A legal name is asked for firmly but never a requirement: OSE needs one only before the collective
// pays or reimburses that admin. So nothing here throws or drops a row. Every row goes on
// to the invitation, and legal_name_check says what the email may claim:
//
//   checked  -> admins_without_legal_name lists who has none, possibly nobody
//   no_scope -> our own host's public legal name came back empty, so the token lacks the
//               account scope and every admin would look empty. Say nothing to the applicant.
//   failed   -> the request failed or Open Collective returned an error. Say nothing.
//
// Unlike the decision reads, an errors array does not throw here: it would hold back the
// invitation over a request. It is reported in the Slack thread instead, so it is not
// silent. The one error that is expected, an admin whose profile no longer exists, skips
// that admin alone.
const parseAdmins = (value) => {
  try {
    const parsed = JSON.parse(value || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
};
const out = [];
$input.all().forEach((item, i) => {
  // When the HTTP node fails as a whole, a credential error for example, n8n passes its
  // input rows through unchanged. Such an item is the row itself, so use it as the row
  // rather than trust paired items to find it.
  const passedThrough = item.json && typeof item.json.slug === 'string' && !('data' in item.json);
  const row = passedThrough ? item.json : $('Still pending on Open Collective?').itemMatching(i).json;
  const admins = parseAdmins(row.oc_admins)
    .filter((a) => a && typeof a.slug === 'string' && a.slug !== '');
  const res = passedThrough ? { error: { message: 'the request did not run' } } : (item.json || {});
  const errors = Array.isArray(res.errors) ? res.errors : [];
  const goneSlugs = new Set();
  const unexpected = errors.filter((e) => {
    const match = /^No collective found with slug (.+)$/.exec((e && e.message) || '');
    if (match && admins.some((a) => a.slug === match[1])) {
      goneSlugs.add(match[1]);
      return false;
    }
    return true;
  });
  const data = res.data;
  let check = 'checked';
  let reason = '';
  const missing = [];
  if (res.error || !data || unexpected.length) {
    check = 'failed';
    reason = res.error
      ? String(res.error.message || res.error)
      : (unexpected.length ? String(unexpected[0].message || 'unknown error') : 'no data in the response');
  } else if (!data.host || !String(data.host.legalName || '').trim()) {
    check = 'no_scope';
  } else {
    admins.forEach((admin, k) => {
      if (goneSlugs.has(admin.slug)) return;
      const account = data['a' + k];
      if (!account) return;
      if (!String(account.legalName || '').trim()) {
        missing.push(String(admin.name || admin.slug).replace(/\s+/g, ' ').trim());
      }
    });
  }
  out.push({ json: {
    ...row,
    legal_name_check: check,
    legal_name_check_reason: reason.slice(0, 300),
    admins_without_legal_name: missing,
  }, pairedItem: { item: i } });
});
return out;

// Rows whose parent message never got posted are skipped rather than posted loose in the
// channel: a reply with no thread_ts lands in the channel with no context.
//
// The only interpolated values are the other host's slug, which comes from the Open
// Collective API, and a duration this node computes. The slug is escaped: & first, then
// < and >, so Slack reads it as text and not as a control sequence.
//
// Mark the invitation skipped returns the updated row and not the reading, so the reading
// is looked up by slug from Read the decision before inviting.
const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const reading = new Map($('Read the decision before inviting').all()
  .map((item) => [item.json.slug, item.json]));

// Open Collective can tell us when the application arrived and when it was approved, but
// not where the collective was hosted before. So the timing is stated as fact and the
// reason only as a likelihood, and only when the approval was fast enough for a
// pre-arranged move to be the likely story.
const minutesBetween = (from, to) => {
  const ms = new Date(to).getTime() - new Date(from).getTime();
  return Number.isFinite(ms) && ms >= 0 ? Math.floor(ms / 60000) : null;
};
const timing = (minutes) => {
  if (minutes === null) return '';
  if (minutes < 1) return 'within a minute of its arrival, ';
  if (minutes < 120) return `${minutes} minute${minutes === 1 ? '' : 's'} after it arrived, `;
  const hours = Math.round(minutes / 60);
  if (hours < 48) return `${hours} hours after it arrived, `;
  return `${Math.round(hours / 24)} days after it arrived, `;
};

const approved = (state) => {
  const minutes = minutesBetween(state.applied_at, state.oc_approved_at);
  let text = `:fast_forward: Form invitation not sent. Open Collective approved the application ${timing(minutes)}before the invitation went out, so there was nothing left to ask.`;
  if (minutes !== null && minutes < 60) {
    text += ' Probably a move from another host agreed with OSE in advance. The applicant\'s own message in this thread usually says so.';
  }
  return text;
};

const TEXTS = {
  approved,
  rejected: () => ':fast_forward: Form invitation not sent. The application is no longer open on Open Collective, so it was rejected or withdrawn before the invitation went out.',
  elsewhere: (state) => `:fast_forward: Form invitation not sent. The collective is now hosted by *${escapeSlack(state.oc_other_host)}*, not by us.`,
  gone: () => ':fast_forward: Form invitation not sent. The collective no longer exists on Open Collective.',
};

const out = [];
$input.all().forEach((item) => {
  const row = item.json;
  if (!row.slack_thread_ts || !row.slack_channel_id) return;
  const state = reading.get(row.slug);
  const text = state && TEXTS[state.oc_state] ? TEXTS[state.oc_state](state) : null;
  if (!text) return;
  out.push({ json: {
    slug: row.slug,
    channel: row.slack_channel_id,
    thread_ts: row.slack_thread_ts,
    text,
  } });
});
return out;
